import React from 'react';
import { Container, LoadingBuzzIcon } from './LoadingBuzz.styles';
import { LoadingBuzzTypes } from './LoadingBuzz.types';
import LoadingDots from '../LoadingDots/LoadingDots';

function LoadingBuzzComponent(
  { color = 'mono', size = 'large', dataTestId, ariaLabel, ...props }: LoadingBuzzTypes,
  forwardedRef: React.ForwardedRef<HTMLDivElement>
): JSX.Element {
  return (
    <Container
      size={size}
      data-testid={dataTestId}
      aria-label={ariaLabel}
      {...props}
      ref={forwardedRef}
    >
      <LoadingBuzzIcon size={size} />
      <LoadingDots size={size} color={color} />
    </Container>
  );
}

export const LoadingBuzz = React.forwardRef(LoadingBuzzComponent);
export default LoadingBuzz;
